const state={section:'active',search:'',tag:'',offset:0,limit:20,total:0,items:[],tags:[],pendingTags:[],deleteId:null};
const $=selector=>document.querySelector(selector);
const list=$('#bookmark-list'),toast=$('#toast');

async function request(path,options={}){const response=await fetch(path,{headers:{'content-type':'application/json'},...options});const payload=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(payload.error||'Something went wrong');error.status=response.status;error.payload=payload;throw error}return payload}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function showToast(message,type='success'){toast.textContent=message;toast.className=`toast show ${type}`;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.className='toast',5000)}
function sectionCopy(){return {active:['Your bookmark library','All bookmarks','The useful parts of the web, kept close.'], 'read-later':['Your reading queue','Read later','Things you’ve saved for a quieter moment.'],archive:['Tucked away, not gone','Archive','Bookmarks you’ve set aside and can restore.']}[state.section]}
function formatDate(value){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(value))}

async function refreshSummary(){const summary=await request('/api/summary');$('#active-count').textContent=summary.active;$('#read-later-count').textContent=summary.readLater;$('#archive-count').textContent=summary.archive}
async function refreshTags(){state.tags=await request(`/api/tags?section=${encodeURIComponent(state.section)}`);renderTagFilters();renderSuggestions()}
function renderTagFilters(){const panel=$('#tag-panel');panel.style.display=state.tags.length?'block':'none';$('#tag-filters').innerHTML=`<button class="tag-filter ${!state.tag?'active':''}" data-tag=""><span>All</span><span>${state.total}</span></button>`+state.tags.map(tag=>`<button class="tag-filter ${state.tag===tag.name?'active':''}" data-tag="${escapeHtml(tag.name)}"><span>${escapeHtml(tag.name)}</span><span>${tag.count}</span></button>`).join('');document.querySelectorAll('.tag-filter').forEach(button=>button.onclick=()=>{state.tag=button.dataset.tag;loadBookmarks(true)})}
function renderSuggestions(){const available=state.tags.filter(tag=>!state.pendingTags.includes(tag.name)).slice(0,8);$('#suggestions').innerHTML=available.length?`<span class="suggestion-label">Used before</span>${available.map(tag=>`<button type="button" class="suggestion" data-suggestion="${escapeHtml(tag.name)}">${escapeHtml(tag.name)}</button>`).join('')}`:'';document.querySelectorAll('[data-suggestion]').forEach(button=>button.onclick=()=>addPendingTag(button.dataset.suggestion))}
function addPendingTag(value){const tag=value.trim().toLowerCase();if(!tag||state.pendingTags.includes(tag))return;state.pendingTags.push(tag);renderPendingTags();renderSuggestions()}
function renderPendingTags(){$('#pending-tags').innerHTML=state.pendingTags.map(tag=>`<span class="pending-tag">${escapeHtml(tag)}<button type="button" data-remove-tag="${escapeHtml(tag)}" aria-label="Remove ${escapeHtml(tag)}">×</button></span>`).join('');document.querySelectorAll('[data-remove-tag]').forEach(button=>button.onclick=()=>{state.pendingTags=state.pendingTags.filter(tag=>tag!==button.dataset.removeTag);renderPendingTags();renderSuggestions()})}

function emptyCopy(){if(state.search)return ['No bookmarks match that search.','Your library is unchanged. Adjust the search and try again.'];if(state.tag)return [`No bookmarks use “${state.tag}” here.`,'Choose another tag or show all bookmarks.'];if(state.section==='read-later')return ['Nothing waiting to be read.','Choose Add to Read later the next time you save something for later.'];if(state.section==='archive')return ['Your archive is empty.','Bookmarks you set aside will appear here.'];return ['Your library is ready.','Save your first link to get started.']}
function cardHtml(item){const note=item.note?`<div class="card-note"><div class="note-copy">${escapeHtml(item.note)}</div>${item.note.length>150?'<button class="show-note">Show full note</button>':''}</div>`:'';const check=state.section==='read-later'?`<input type="checkbox" class="complete-check" data-complete="${item.id}" aria-label="Finished with ${escapeHtml(item.title)}">`:'';const status=[];if(item.readLater)status.push('<span class="status-chip reading">Read later</span>');if(item.metadataStatus==='unavailable')status.push('<span class="status-chip">Details unavailable</span>');const menu=state.section==='archive'?`<button data-action="restore">Restore to All bookmarks</button><button data-action="edit">Edit details</button><button class="delete-action" data-action="delete">Delete permanently…</button>`:`<button data-action="edit">Edit details</button><button data-action="archive">Archive</button><button class="delete-action" data-action="delete">Delete permanently…</button>`;return `<article class="bookmark-card ${state.section==='read-later'?'read-later-card':''}" data-id="${item.id}">${check}<div class="card-main"><a class="card-title" href="${escapeHtml(item.url)}" target="_blank" rel="noopener">${escapeHtml(item.title||item.url)}</a>${item.description?`<p class="card-description">${escapeHtml(item.description)}</p>`:''}<div class="card-url" title="${escapeHtml(item.url)}">${escapeHtml(item.url)}</div>${item.tags.length?`<div class="card-tags">${item.tags.map(tag=>`<span class="tag-chip">${escapeHtml(tag)}</span>`).join('')}</div>`:''}${note}${status.length?`<div class="status-row">${status.join('')}</div>`:''}</div><div class="card-side"><span class="saved-date">${formatDate(item.createdAt)}</span><button class="more-button" aria-label="Actions for ${escapeHtml(item.title)}">•••</button><div class="card-menu">${menu}</div></div></article>`}
function bindCards(){document.querySelectorAll('.more-button').forEach(button=>button.onclick=event=>{event.stopPropagation();const menu=button.nextElementSibling;document.querySelectorAll('.card-menu.open').forEach(open=>{if(open!==menu)open.classList.remove('open')});menu.classList.toggle('open')});document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>handleAction(button.closest('.bookmark-card').dataset.id,button.dataset.action));document.querySelectorAll('[data-complete]').forEach(input=>input.onchange=()=>completeReadLater(input.dataset.complete));document.querySelectorAll('.show-note').forEach(button=>button.onclick=()=>{button.closest('.card-note').classList.add('expanded');button.remove()})}
function renderList(){if(!state.items.length){const [title,detail]=emptyCopy();list.innerHTML=`<div class="empty-state"><strong>${escapeHtml(title)}</strong>${escapeHtml(detail)}</div>`}else list.innerHTML=state.items.map(cardHtml).join('');$('#result-count').textContent=`${state.total} ${state.total===1?'bookmark':'bookmarks'}`;$('#load-more').classList.toggle('show',state.items.length<state.total);bindCards();renderTagFilters()}
async function loadBookmarks(reset=true){if(reset){state.offset=0;state.items=[];list.innerHTML='<div class="loading">Loading your bookmarks…</div>'}const params=new URLSearchParams({section:state.section,search:state.search,tag:state.tag,offset:String(state.offset),limit:String(state.limit)});try{const data=await request(`/api/bookmarks?${params}`);state.items=reset?data.items:[...state.items,...data.items];state.total=data.total;renderList();await Promise.all([refreshSummary(),refreshTags()]);if(!$('#main').hasAttribute('data-harness-ready'))$('#main').setAttribute('data-harness-ready','true')}catch{list.innerHTML='<div class="empty-state"><strong>Couldn’t load your library.</strong>Refresh the page to try again.</div>'}}
async function switchSection(section){state.section=section;state.search='';state.tag='';$('#search').value='';document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.section===section));const [eyebrow,title,subtitle]=sectionCopy();$('#eyebrow').textContent=eyebrow;$('#section-title').textContent=title;$('#section-subtitle').textContent=subtitle;$('#list-title').textContent=section==='active'?'Recently saved':title;$('#open-save').style.display=section==='active'?'block':'none';$('#save-panel').classList.remove('open');await loadBookmarks(true)}

async function saveBookmark(event){event.preventDefault();const field=$('#url').closest('.field-grow'),button=$('.save-submit');field.classList.remove('invalid');$('#url-error').textContent='';button.disabled=true;button.textContent='Getting details…';try{const data=await request('/api/bookmarks',{method:'POST',body:JSON.stringify({url:$('#url').value,note:$('#note').value,tags:state.pendingTags,readLater:$('#read-later').checked})});const unavailable=data.bookmark.metadataStatus==='unavailable';showToast(unavailable?'Saved using the web address because page details weren’t available. You can edit the details later.':'Link saved and page details added.',unavailable?'warning':'success');resetSaveForm();await loadBookmarks(true);highlight(data.bookmark.id)}catch(error){if(error.status===422){field.classList.add('invalid');$('#url-error').textContent=error.message;$('#url').focus()}else if(error.status===409){showToast('Already saved — here’s your existing bookmark.','warning');if(error.payload.bookmark.archivedAt)await switchSection('archive');else if(state.section==='archive')await switchSection('active');else await loadBookmarks(true);highlight(error.payload.bookmark.id)}else showToast('The link could not be saved. Your library was not changed.','warning')}finally{button.disabled=false;button.textContent='Save link'}}
function resetSaveForm(){$('#save-form').reset();state.pendingTags=[];renderPendingTags();$('#note-field').classList.remove('open');$('#add-note').style.display='inline-block';$('#save-panel').classList.remove('open')}
function highlight(id){requestAnimationFrame(()=>{const card=document.querySelector(`[data-id="${CSS.escape(id)}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.classList.add('highlight');setTimeout(()=>card.classList.remove('highlight'),3200)}})}
async function completeReadLater(id){await request(`/api/bookmarks/${id}/complete-read-later`,{method:'POST',body:'{}'});showToast('Removed from Read later. The bookmark is still in All bookmarks.');await loadBookmarks(true)}
function findItem(id){return state.items.find(item=>item.id===id)}
async function handleAction(id,action){const item=findItem(id);if(action==='archive'){await request(`/api/bookmarks/${id}/archive`,{method:'POST',body:'{}'});showToast('Moved to Archive. You can still find and restore it there.');await loadBookmarks(true)}if(action==='restore'){await request(`/api/bookmarks/${id}/restore`,{method:'POST',body:'{}'});showToast(`${item.title} restored to All bookmarks.`);await loadBookmarks(true)}if(action==='edit')openEdit(item);if(action==='delete'){state.deleteId=id;$('#delete-title').textContent=`Delete ${item.title}?`;$('#delete-dialog').showModal()}}
function openEdit(item){$('#edit-id').value=item.id;$('#edit-title').value=item.title;$('#edit-description').value=item.description;$('#edit-note').value=item.note;$('#edit-tags').value=item.tags.join(', ');$('#edit-read-later').checked=item.readLater;$('#edit-read-later').disabled=Boolean(item.archivedAt);$('#edit-dialog').showModal()}
async function saveEdit(event){event.preventDefault();const id=$('#edit-id').value;await request(`/api/bookmarks/${id}`,{method:'PATCH',body:JSON.stringify({title:$('#edit-title').value,description:$('#edit-description').value,note:$('#edit-note').value,tags:$('#edit-tags').value.split(','),readLater:$('#edit-read-later').checked})});$('#edit-dialog').close();showToast('Bookmark details updated.');await loadBookmarks(true);highlight(id)}
async function deleteBookmark(event){event.preventDefault();await request(`/api/bookmarks/${state.deleteId}`,{method:'DELETE'});$('#delete-dialog').close();showToast('Bookmark permanently deleted.','warning');state.deleteId=null;await loadBookmarks(true)}

$('#sections').addEventListener('click',event=>{const button=event.target.closest('[data-section]');if(button)switchSection(button.dataset.section)});$('#open-save').onclick=()=>{$('#save-panel').classList.add('open');$('#url').focus()};$('#close-save').onclick=()=>$('#save-panel').classList.remove('open');$('#add-note').onclick=()=>{$('#note-field').classList.add('open');$('#add-note').style.display='none';$('#note').focus()};$('#tag-entry').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();addPendingTag(event.currentTarget.value);event.currentTarget.value=''}});$('#save-form').addEventListener('submit',saveBookmark);$('#load-more').onclick=()=>{state.offset=state.items.length;loadBookmarks(false)};let searchTimer;$('#search').addEventListener('input',event=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.search=event.target.value.trim();loadBookmarks(true)},180)});$('#edit-form').addEventListener('submit',saveEdit);$('#confirm-delete').addEventListener('click',deleteBookmark);document.addEventListener('click',event=>{if(!event.target.closest('.card-side'))document.querySelectorAll('.card-menu.open').forEach(menu=>menu.classList.remove('open'))});

loadBookmarks(true);

